  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Are the weekly demand figures (e.g., 10,000 kg of food I in week 1) hard requirements that must be met exactly on time each week, or are they targets that may be delivered late (incurring the stated compensation fee per kg per week of delay)?"
  ],
  "rationale": "The response contains a single clarification question asking for a policy choice between hard requirements and flexible targets with penalties."
}

